const routes=[{origin:"Gorakhpur",destination:"Anand Vihar (Delhi)",importantStations:["Gonda","Lucknow","Kanpur","Moradabad"],regions:["Uttar Pradesh","Delhi"]},{origin:"Bandra Terminus",destination:"Saharsa",importantStations:["Surat","Bhusaval","Jabalpur","Patna"],regions:["Maharashtra","Gujarat","Madhya Pradesh","Bihar"]},{origin:"Kamakhya (Guwahati)",destination:"Bengaluru Cantt",importantStations:["New Jalpaiguri","Howrah","Bhubaneswar","Vijayawada"],regions:["Assam","West Bengal","Odisha","Andhra Pradesh","Karnataka"]},{origin:"Ajmer",destination:"Sealdah (Kolkata)",importantStations:["Jaipur","Agra Fort","Kanpur","Dhanbad"],regions:["Rajasthan","Uttar Pradesh","Jharkhand","West Bengal"]}],amenities=[{title:"Plush Berths",description:"Comfortable side-berths and main berths with improved cushioning and fire-retardant upholstery.",icon:"fa-solid fa-bed"},{title:"Charging Facilities",description:"Multiple mobile and laptop charging points provided for every passenger, along with USB slots in newer coaches.",icon:"fa-solid fa-plug"},{title:"Passenger Info System",description:"GPS-based display boards showing train speed, next station, and expected time of arrival.",icon:"fa-solid fa-tv"},{title:"Catering",description:"Optional catering services with well-maintained pantry cars and tea/coffee vending machines on board.",icon:"fa-solid fa-utensils"},{title:"Reading Lights",description:"Individual LED reading lights provided for every berth to ensure convenience without disturbing others.",icon:"fa-regular fa-lightbulb"},{title:"Safety Features",description:"Extensive CCTV surveillance in aisles and vestibules, plus smoke and fire detection systems.",icon:"fa-solid fa-shield-halved"}];function renderAmenities(){const i=document.querySelector(".amenities-grid");i&&(i.innerHTML=amenities.map(i=>`\n    <div class="card">\n      <i class="${i.icon}" style="font-size: 2rem; color: var(--humsafar-orange); margin-bottom: 15px;"></i>\n      <h3>${i.title}</h3>\n      <p>${i.description}</p>\n    </div>\n  `).join(""))}function renderRoutes(){const i=document.getElementById("routes-container");i&&(i.innerHTML=routes.map(i=>`\n    <div class="route-card">\n      <div>\n        <div class="origin-dest">${i.origin} <i class="fa-solid fa-arrow-right" style="color: var(--primary-gold); margin: 0 10px;"></i> ${i.destination}</div>\n        <div class="stations"><strong>Via:</strong> ${i.importantStations.join(", ")}</div>\n      </div>\n      <div>\n        <span style="background: var(--humsafar-blue); padding: 5px 10px; border-radius: 4px; font-size: 0.8rem;">\n          ${i.regions.join(" &middot; ")}\n        </span>\n      </div>\n    </div>\n  `).join(""))}document.addEventListener("DOMContentLoaded",()=>{renderAmenities(),renderRoutes()});